import { installKit } from "@zedkit/ai";
const result = installKit({ dest: ".", preset: "core", providers: ["claude", "cursor"] });
if (!result.ok) throw result.error;
for (const action of result.value) console.log(action.kind, action.path);

import { checkDrift, validateKit } from "@zedkit/ai";
const issues = [...validateKit(".agents"), ...checkDrift(".", ".agents")];
for (const issue of issues) console.error(`${issue.path}: ${issue.message}`);

import { isOk, ok, unwrapOr } from "@zedkit/core";
const found = ok({ name: "zed" });
if (isOk(found)) console.log(found.value.name);
const name = unwrapOr(found, { name: "?" }).name;

import { tryCatch } from "@zedkit/core";
const parsed = tryCatch(() => JSON.parse(input));
if (!parsed.ok) return fallback(parsed.error);

import { isPrefixedId, newPrefixedId } from "@zedkit/core";
const id = newPrefixedId("order"); // order_01M5Q75SHJ9CVV6E3RBF0FGEM1
if (!isPrefixedId(id, "order")) throw new Error("bad id");

import { createNestApp } from "@zedkit/nest";
const app = await createNestApp({ module: AppModule, envSchema: AppEnv });
await app.listen(3000);

import { createNestApp } from "@zedkit/nest";
const app = await createNestApp({
  module: AppModule,
  logger: { level: "info" }, // default: auth header + cookies redacted
});

import { AllExceptionsFilter } from "@zedkit/nest";
// wired globally by createNestApp; reuse standalone:
app.useGlobalFilters(new AllExceptionsFilter());

import { MemoryRateLimiter } from "@zedkit/server";
const limiter = new MemoryRateLimiter();
if (!limiter.allow(clientIp, 100)) return tooManyRequests();

import { computeBackoffMs } from "@zedkit/server";
const waitMs = computeBackoffMs(failedAttemptNo);
await sleep(waitMs);

import { verifyWebhookSignatureHeader as verify } from "@zedkit/server";
if (!verify(secret, rawBody, headers["webhook-signature"], { maxAgeSeconds: 300 })) {
  return unauthorized();
}

import { pgErrorCode } from "@zedkit/server";
try {
  await db.insert(users).values(row);
} catch (error) {
  if (pgErrorCode(error) === "23505") return conflict();
  throw error;
}

